return join(
	' ',
	array_map(
		function ( $key ) use ( $attributes ) {
			if ( is_bool( $attributes[ $key ] ) ) {
				return $attributes[ $key ] ? $key : '';
			}

			return $key . '="' . $attributes[ $key ] . '"';
		},
		array_keys( $attributes )
	)
) . ' ';

